  1967		var relations []semanticRecord
  1968		for level := 0; level < depth && len(frontier) > 0 && len(symbols) < limit; level++ {
  1969			current := make([]semanticRecord, 0, len(frontier))
  1970			for id := range frontier {
  1971				current = append(current, semanticRecord{ID: id})
  1972			}
  1973			edges, err := findSemanticRelationsForSymbolsInSQLite(storePath, current, limit*4)
  1974			if err != nil {
