  2713	func resolvedOutputPath(output string) (string, error) {
  2714		if resolved, err := filepath.EvalSymlinks(output); err == nil {
  2715			return filepath.Abs(resolved)
  2716		}
  2717		absOutput, err := filepath.Abs(output)
  2718		if err != nil {
  2719			return "", err
  2720		}
  2721		volume := filepath.VolumeName(absOutput)
  2722		rest := strings.TrimPrefix(absOutput, volume)
  2723		parts := strings.Split(strings.Trim(rest, string(filepath.Separator)), string(filepath.Separator))
  2724		existing := volume + string(filepath.Separator)
  2725		var missing []string
  2726		for i, part := range parts {
  2727			candidate := filepath.Join(existing, part)
  2728			if _, err := os.Lstat(candidate); err != nil {
  2729				if os.IsNotExist(err) {
  2730					missing = parts[i:]
  2731					break
  2732				}
  2733				return "", err
  2734			}
  2735			existing = candidate
  2736		}
  2737		resolvedExisting, err := filepath.EvalSymlinks(existing)
  2738		if err != nil {
  2739			return "", err
  2740		}
  2741		for _, part := range missing {
  2742			resolvedExisting = filepath.Join(resolvedExisting, part)
  2743		}
  2744		return filepath.Abs(resolvedExisting)
  2745	}
