  2824			if err != nil {
  2825				return err
  2826			}
  2827			_, copyErr := io.CopyN(out, tr, header.Size)
  2828			closeErr := out.Close()
  2829			if copyErr != nil {
  2830				return copyErr
  2831			}
  2832			if closeErr != nil {
  2833				return closeErr
  2834			}
