  2918		backup := target + ".old-" + strconv.FormatInt(time.Now().UnixNano(), 10)
  2919		targetMoved := false
  2920		if _, err := os.Lstat(target); err == nil {
  2921			if err := os.Rename(target, backup); err != nil {
